    Implements basic regex matching using recursion with memoization.
    Supports literal characters, '.' (any char), '*' (zero or more of the preceding element), 
    and '+' (one or more of the preceding).
    """
    def is_match(p: str, t: str, memo: dict) -> bool:
        if (p, t) in memo:
            return memo[(p, t)]

        if not p:
            result = not t
        elif len(p) > 1 and p[1] in '*+':
            if p[1] == '*':
                result = is_match(p[2:], t, memo) or \
                         (t and (p[0] == t[0] or p[0] == '.') and is_match(p, t[1:], memo))
            else:  # p[1] == '+'
                result = (t and (p[0] == t[0] or p[0] == '.') and 
                          (is_match(p, t[1:], memo) or is_match(p[2:], t[1:], memo)))
        else:
            result = t and (p[0] == t[0] or p[0] == '.') and is_match(p[1:], t[1:], memo)

        memo[(p, t)] = result
        return result

