def match(pattern: str, text: str) -> bool:
    """
    Implements basic regex matching using backtracking to handle
    literal characters, '.' (any character), '*' (zero or more of the 
    preceding element), and '+' (one or more of the preceding element).
    """

    def is_match(i: int, j: int) -> bool:
        if j == len(pattern):
            return i == len(text)

        first_match = (i < len(text) and 
                       (pattern[j] == text[i] or pattern[j] == '.'))

        if (j + 1 < len(pattern) and pattern[j + 1] in {'*', '+'}):
            if pattern[j + 1] == '*':
                return (is_match(i, j + 2) or 
                        (first_match and is_match(i + 1, j)))
            elif pattern[j + 1] == '+':
                return (first_match and 
                        (is_match(i + 1, j) or is_match(i + 1, j + 2)))

        return first_match and is_match(i + 1, j + 1)

    return is_match(0, 0)

def match(pattern: str, text: str) -> bool:
    """
    Implements a regex matching algorithm using recursion and dynamic programming.
    Supports literal characters, '.' (matches any character), '*' (matches zero or more),
    and '+' (matches one or more of the preceding element).
    """

    def is_match(p_index: int, t_index: int) -> bool:
        # Base case: if we've processed the entire pattern
        if p_index == len(pattern):
            return t_index == len(text)

        # Check if the current characters match
        first_match = (t_index < len(text) and 
                       (pattern[p_index] == text[t_index] or pattern[p_index] == '.'))

        # Handle '*' (zero or more) and '+' (one or more)
        if p_index + 1 < len(pattern) and pattern[p_index + 1] in ('*', '+'):
            if pattern[p_index + 1] == '*':
                return (is_match(p_index + 2, t_index) or 
                        (first_match and is_match(p_index, t_index + 1)))
            elif pattern[p_index + 1] == '+' and first_match:
                return (is_match(p_index, t_index + 1) or
                        is_match(p_index + 2, t_index))

        # Regular character match
        if first_match:
            return is_match(p_index + 1, t_index + 1)

        return False

    return is_match(0, 0)

