    memo = {}

    def dp(p: int, t: int) -> bool:
        if (p, t) in memo:
            return memo[(p, t)]

        if p == len(pattern):
            result = t == len(text)
        else:
            first_match = t < len(text) and (text[t] == pattern[p] or pattern[p] == '.')

            if p + 1 < len(pattern) and pattern[p + 1] in ('*', '+'):
                if pattern[p + 1] == '*':
                    result = (dp(p + 2, t) or 
                              (first_match and dp(p, t + 1)))
                else:  # pattern[p + 1] == '+'
                    result = first_match and (dp(p, t + 1) or dp(p + 2, t))
            else:
                result = first_match and dp(p + 1, t + 1)

        memo[(p, t)] = result
        return result

    return dp(0, 0)

